// Some portions generated by Co-Pilot
import { fireEvent, render, screen } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { axe } from "vitest-axe";
import ReleaseFilters from "../index";
import { useOses, useArches } from "@/hooks/fetchConstants";

vi.mock("@/hooks/fetchConstants", () => ({
  useOses: vi.fn(),
  useArches: vi.fn(),
}));

const props = {
  version: "21",
  os: "linux",
  arch: "x64",
  latestLTS: 25,
  allVersions: [
    { name: "25 - LTS", value: "25" },
    { name: "21 - LTS", value: "21" },
    { name: "17 - LTS", value: "17" },
  ],
  onFiltersChange: vi.fn(),
};

describe("Controlled release filters", () => {
  beforeEach(() => {
    vi.clearAllMocks();
    vi.mocked(useOses).mockReturnValue([
      { name: "Linux", value: "linux" },
      { name: "Windows", value: "windows" },
    ]);
    vi.mocked(useArches).mockReturnValue([
      { name: "x64", value: "x64" },
      { name: "aarch64", value: "aarch64" },
    ]);
  });

  it("uses the supplied URL-derived values without triggering an initial fetch", () => {
    render(<ReleaseFilters {...props} />);
    expect(screen.getByTestId("version-selector")).toHaveValue("21");
    expect(screen.getByTestId("os-selector")).toHaveValue("linux");
    expect(screen.getByTestId("arch-selector")).toHaveValue("x64");
    expect(props.onFiltersChange).not.toHaveBeenCalled();
  });

  it("preserves the version and architecture when changing OS", () => {
    render(<ReleaseFilters {...props} />);
    fireEvent.change(screen.getByTestId("os-selector"), {
      target: { value: "windows" },
    });
    expect(props.onFiltersChange).toHaveBeenCalledWith("21", "windows", "x64");
  });

  it("preserves the version and OS when changing architecture", () => {
    render(<ReleaseFilters {...props} />);
    fireEvent.change(screen.getByTestId("arch-selector"), {
      target: { value: "aarch64" },
    });
    expect(props.onFiltersChange).toHaveBeenCalledWith(
      "21",
      "linux",
      "aarch64",
    );
  });

  it("resets platform filters when choosing another version", () => {
    render(<ReleaseFilters {...props} />);
    fireEvent.change(screen.getByTestId("version-selector"), {
      target: { value: "17" },
    });
    expect(props.onFiltersChange).toHaveBeenCalledWith("17", "any", "any");
  });

  it("resets to the supplied latest LTS", () => {
    render(<ReleaseFilters {...props} />);
    fireEvent.click(screen.getByTestId("reset-filters-button"));
    expect(props.onFiltersChange).toHaveBeenCalledWith("25", "any", "any");
  });

  it("reflects URL changes from the parent", () => {
    const { rerender } = render(<ReleaseFilters {...props} />);
    rerender(
      <ReleaseFilters {...props} version="17" os="windows" arch="aarch64" />,
    );
    expect(screen.getByTestId("version-selector")).toHaveValue("17");
    expect(screen.getByTestId("os-selector")).toHaveValue("windows");
    expect(screen.getByTestId("arch-selector")).toHaveValue("aarch64");
  });

  it("disables version selection while the options are unavailable", () => {
    render(<ReleaseFilters {...props} allVersions={[]} />);
    expect(screen.getByTestId("version-selector")).toBeDisabled();
  });

  it("labels native selectors accessibly", async () => {
    const { container } = render(<ReleaseFilters {...props} />);
    expect(screen.getAllByRole("combobox")).toHaveLength(3);
    for (const selector of screen.getAllByRole("combobox"))
      expect(selector).toHaveAccessibleName();
    expect(await axe(container)).toHaveNoViolations();
  });
});
